CREATE OR REPLACE FUNCTION public.notify_on_activity_comment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_author uuid;
  v_href text;
begin
  select p.author_id, public.post_href(p.id)
  into v_author, v_href
  from public.activity_posts p
  where p.id = new.post_id;

  perform public.notify(
    v_author, 'comment', 'engagement',
    public.actor_name(new.author_id) || ' commented on your update',
    left(new.body, 140), v_href, new.author_id
  );
  return new;
end;
$function$;

grant execute on function public.notify_on_activity_comment() to anon;
grant execute on function public.notify_on_activity_comment() to authenticated;
grant execute on function public.notify_on_activity_comment() to public;
grant execute on function public.notify_on_activity_comment() to service_role;
